package com.epms.desktop.api;
import com.epms.desktop.model.Employee; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import java.net.URI; import java.net.http.*; import java.util.*; import java.util.concurrent.*;
public class ApiClient {private final HttpClient http=HttpClient.newHttpClient();private final ObjectMapper om=new ObjectMapper().registerModule(new JavaTimeModule()).configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,false).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);private final String base="http://localhost:8090/api";private String token;
 public String getBase(){return base;}
 private HttpRequest.Builder req(String path){var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json");if(token!=null)b.header("Authorization","Bearer "+token);return b;}
 public String login(String user,String pass)throws Exception{var body=om.writeValueAsString(Map.of("username",user,"password",pass));var r=http.send(req("/auth/login").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException("Login failed: "+r.body());var n=om.readTree(r.body());token=n.get("token").asText();return n.get("role").asText();}
 public List<Employee> employees(String q)throws Exception{String p=q==null||q.isBlank()?"/employees":"/employees?q="+java.net.URLEncoder.encode(q,java.nio.charset.StandardCharsets.UTF_8);var r=http.send(req(p).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return Arrays.asList(om.readValue(r.body(),Employee[].class));}
 public Employee save(Employee e)throws Exception{var r=http.send(req("/employees").POST(HttpRequest.BodyPublishers.ofString(om.writeValueAsString(e))).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readValue(r.body(),Employee.class);}
 public Employee update(Long id,Employee e)throws Exception{var r=http.send(req("/employees/"+id).PUT(HttpRequest.BodyPublishers.ofString(om.writeValueAsString(e))).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readValue(r.body(),Employee.class);}
 public void delete(Long id)throws Exception{var r=http.send(req("/employees/"+id).DELETE().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new RuntimeException(r.body());}
 public JsonNode calculate(Map<String,Object> payload)throws Exception{var r=http.send(req("/payroll/calculate").POST(HttpRequest.BodyPublishers.ofString(om.writeValueAsString(payload))).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public JsonNode savePayroll(Map<String,Object> payload)throws Exception{var r=http.send(req("/payroll/save").POST(HttpRequest.BodyPublishers.ofString(om.writeValueAsString(payload))).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public List<JsonNode> payrollHistory(Long employeeId)throws Exception{var r=http.send(req("/payroll/employee/"+employeeId).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public JsonNode clockIn(Long employeeId)throws Exception{var body=om.writeValueAsString(Map.of("employeeId",employeeId));var r=http.send(req("/time-entries/clock-in").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public JsonNode clockOut(Long entryId)throws Exception{var r=http.send(req("/time-entries/"+entryId+"/clock-out").POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public List<JsonNode> timeEntries(Long employeeId)throws Exception{var r=http.send(req("/time-entries/employee/"+employeeId).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}

 public List<JsonNode> journalEntries(Long employeeId)throws Exception{String p=employeeId==null?"/accounting/journal":"/accounting/journal?employeeId="+employeeId;var r=http.send(req(p).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public List<JsonNode> accountBalances()throws Exception{var r=http.send(req("/accounting/balances").GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public JsonNode ytdTax(Long employeeId,Integer year)throws Exception{String p="/tax/ytd/"+employeeId+(year!=null?"?year="+year:"");var r=http.send(req(p).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public JsonNode w2(Long employeeId,int year)throws Exception{var r=http.send(req("/w2/"+employeeId+"/"+year).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public List<JsonNode> w2ByYear(int year)throws Exception{var r=http.send(req("/w2/year/"+year).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}

 public List<JsonNode> allPayrolls()throws Exception{var r=http.send(req("/payroll").GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public JsonNode updatePayrollStatus(Long id,String status)throws Exception{var body=om.writeValueAsString(Map.of("status",status));var r=http.send(req("/payroll/"+id+"/status").method("PATCH",HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public Employee setEmployeeActive(Long id,boolean active)throws Exception{var body=om.writeValueAsString(Map.of("active",active));var r=http.send(req("/employees/"+id+"/status").method("PATCH",HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readValue(r.body(),Employee.class);}
 public List<JsonNode> allTimeEntries()throws Exception{var r=http.send(req("/time-entries").GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public List<JsonNode> ytdAll(Integer year)throws Exception{String p="/tax/ytd-all"+(year!=null?"?year="+year:"");var r=http.send(req(p).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}

 public JsonNode voidPayroll(Long id,String reason)throws Exception{var body=om.writeValueAsString(Map.of("reason",reason==null?"":reason));var r=http.send(req("/payroll/"+id+"/void").method("PATCH",HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public JsonNode reversePayroll(Long id,String reason)throws Exception{var body=om.writeValueAsString(Map.of("reason",reason==null?"":reason));var r=http.send(req("/payroll/"+id+"/reverse").method("PATCH",HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());return om.readTree(r.body());}
 public List<JsonNode> auditAll()throws Exception{var r=http.send(req("/audit").GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
 public List<JsonNode> auditForEntity(String type,Long id)throws Exception{var r=http.send(req("/audit/entity?type="+type+"&id="+id).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new RuntimeException(r.body());List<JsonNode> list=new ArrayList<>();om.readTree(r.body()).forEach(list::add);return list;}
}
